def finish_episode(self) -> dict[str, Path]:
    """Flush all encoders, wait for completion, return {key: video_path}."""
    paths = {}
    for key, enc in self._encoders.items():
        paths[key] = enc.finish()
    self._encoders.clear()
    return paths
